{
        "@context": "https://schema.org",
        "@type": "FAQPage",
        "mainEntity": [
            {
                "@type": "Question",
                "name": "연금보험료 계산 시 단수 처리는 어떻게 이루어지나요?",
                "acceptedAnswer": {
                    "@type": "Answer",
                    "text": "👉 국민연금법 제117조 및 국고금 관리법 제47조에 의거하여, 계산 과정에서 발생하는 10원 미만의 끝수(원 단위)는 절사(버림) 처리됩니다."
                }
            },
            {
                "@type": "Question",
                "name": "직장인과 자영업자의 연금보험료 납부 명칭이 다른가요?",
                "acceptedAnswer": {
                    "@type": "Answer",
                    "text": "👉 직장인(사업장가입자)의 부담분은 근로자 부담분을 '기여금', 사용자 부담분을 '부담금'이라 부르며, 지역가입자는 '연금보험료'로 부릅니다."
                }
            },
            {
                "@type": "Question",
                "name": "소득이 있는 경우 모든 금액에 국민연금 보험료율이 적용되나요?",
                "acceptedAnswer": {
                    "@type": "Answer",
                    "text": "👉 아닙니다. 비과세 근로소득 등을 제외한 기준소득월액을 기초로 산정하며, 상한액과 하한액 범위 내에서 결정됩니다."
                }
            }
        ]
    }

customCss:
.single-summary-card-container {
            font-family: 'Noto Sans KR', sans-serif;
            display: flex;
            justify-content: center;
            align-items: center;
            padding: 20px 10px;
            background-color: #e9ecef;
            margin: 20px 0;
            border-radius: 8px;
        }
        .single-summary-card {
            width: 100%;
            max-width: 700px;
            background-color: #ffffff;
            border-radius: 12px;
            box-shadow: 0 6px 18px rgba(0,0,0,0.08);
            padding: 25px;
            display: flex;
            flex-direction: column;
            border: 1px solid #ced4da;
            box-sizing: border-box;
        }
        .single-summary-card .card-header {
            display: flex;
            align-items: center;
            border-bottom: 2px solid #004085;
            padding-bottom: 12px;
            margin-bottom: 15px;
        }
        .single-summary-card .card-header-icon {
            font-size: 32px;
            color: #004085;
            margin-right: 12px;
        }
        .single-summary-card .card-header h3 {
            font-size: 22px;
            color: #004085;
            margin: 0;
            font-weight: 700;
        }
        .single-summary-card .card-content {
            font-size: 16px;
            line-height: 1.6;
            color: #333333;
        }
        .single-summary-card .card-content .section {
            margin-bottom: 12px;
        }
        .single-summary-card .card-content strong {
            color: #002752;
        }
        .single-summary-card .card-content .formula {
            background-color: #f1f3f5;
            padding: 8px 12px;
            border-radius: 4px;
            font-size: 0.95em;
            text-align: center;
            margin-top: 6px;
            color: #004085;
            font-weight: bold;
            border: 1px dashed #b8daff;
        }
        .single-summary-card .card-footer {
            font-size: 13px;
            color: #6c757d;
            text-align: center;
            padding-top: 12px;
            border-top: 1px dashed #dee2e6;
            margin-top: 10px;
        }
        @media (max-width: 768px) {
            .single-summary-card { padding: 18px; }
            .single-summary-card .card-header h3 { font-size: 19px; }
            .single-summary-card .card-content { font-size: 14px; }
        }
